/* Yaoki offline copy. Generated by build.mjs: the file list and the version are filled in at build time.
 * Every file of the app is stored on the phone when this installs, and served from there afterwards,
 * so the app opens without a connection. A new build has a new version, which replaces the stored copy. */
const VERSION = '82700556f4';
/* the store is named after the folder this copy of the app lives in: a second copy under the same web
   address (another level, a trial version) keeps its own store and never touches this one */
const HOME = new URL('./', self.location.href).pathname;
const PREFIX = 'yaoki:' + HOME + ':';
const CACHE = PREFIX + VERSION;
const FILES = [
 "./",
 "./assets/app.css",
 "./assets/build.js",
 "./assets/course-n2.js",
 "./assets/course-n3.js",
 "./assets/course-n4.js",
 "./assets/course-n5.js",
 "./assets/course.js",
 "./assets/fonts.css",
 "./assets/fonts/klee-one-400.woff2",
 "./assets/fonts/klee-one-600.woff2",
 "./assets/fonts/mplus-rounded-1c-500.woff2",
 "./assets/fonts/mplus-rounded-1c-700.woff2",
 "./assets/fonts/mplus-rounded-1c-800.woff2",
 "./assets/preact.min.js",
 "./assets/screens.css",
 "./assets/screens.js",
 "./assets/sound-course.js",
 "./assets/sound-lessons.js",
 "./assets/sound-mock.js",
 "./assets/sound.js",
 "./assets/yk-app.js",
 "./assets/yk-runtime.js",
 "./icons/apple-touch-icon.png",
 "./icons/favicon-32.png",
 "./icons/icon-192.png",
 "./icons/icon-512-maskable.png",
 "./icons/icon-512.png",
 "./index.html",
 "./licenses.txt",
 "./manifest.webmanifest"
];
/* each level's sound, one file per unit, is not part of the install (it would make the first download several
   times larger): a unit's file is stored the first time it is used, and the app asks for the rest of the chosen
   level in the background. Each file carries a hash of its content, so a new build keeps the ones that did not change. */
const LAZY = {
 "./assets/sound-course-n3-u00.js": "85219b5958",
 "./assets/sound-course-n3-u01.js": "181f4f71da",
 "./assets/sound-course-n3-u02.js": "d81ac6355e",
 "./assets/sound-course-n3-u03.js": "1e391919ae",
 "./assets/sound-course-n3-u04.js": "c65b20a030",
 "./assets/sound-course-n3-u05.js": "2545011068",
 "./assets/sound-course-n3-u06.js": "b482ca49b3",
 "./assets/sound-course-n3-u07.js": "8a38b5cc94",
 "./assets/sound-course-n3-u08.js": "355c4cb6ff",
 "./assets/sound-course-n3-u09.js": "502c9e2d2a",
 "./assets/sound-course-n3-u10.js": "81f7c22748",
 "./assets/sound-course-n3-u11.js": "cb900c59af",
 "./assets/sound-course-n3-u12.js": "1bb05ac953",
 "./assets/sound-course-n4-u00.js": "892e97dc8f",
 "./assets/sound-course-n4-u01.js": "89d43bc6bd",
 "./assets/sound-course-n4-u02.js": "916b43e31a",
 "./assets/sound-course-n4-u03.js": "3c54c4417b",
 "./assets/sound-course-n4-u04.js": "bffbf2d476",
 "./assets/sound-course-n4-u05.js": "44531face2",
 "./assets/sound-course-n4-u06.js": "e8e71998d1",
 "./assets/sound-course-n4-u07.js": "4b963087cd",
 "./assets/sound-course-n4-u08.js": "55b1062e75",
 "./assets/sound-course-n4-u09.js": "99d04a8786",
 "./assets/sound-course-n4-u10.js": "2b8625aa7d",
 "./assets/sound-course-n5-u00.js": "cf2d0b58ce",
 "./assets/sound-course-n5-u01.js": "50cb6444ec",
 "./assets/sound-course-n5-u02.js": "ccbba3e844",
 "./assets/sound-course-n5-u03.js": "50281cd049",
 "./assets/sound-course-n5-u04.js": "f19c1367f4",
 "./assets/sound-course-n5-u05.js": "0b824235e4",
 "./assets/sound-course-n5-u06.js": "bb75ef9249",
 "./assets/sound-course-n5-u07.js": "7dcdd3fde1",
 "./assets/sound-course-n5-u08.js": "19a5b1e959"
};
const lazyKey = (f) => f + '?h=' + LAZY[f];
const lazyOf = (url) => { const p = './' + new URL(url).pathname.slice(HOME.length); return LAZY[p] ? p : null; };
async function keepLazy(cache, f) {
  if (await cache.match(lazyKey(f))) return;
  /* a copy already stored by an earlier build, if its content is the same */
  for (const k of await caches.keys()) {
    if (!k.startsWith(PREFIX) || k === CACHE) continue;
    const old = await (await caches.open(k)).match(lazyKey(f));
    if (old) { await cache.put(lazyKey(f), old); return; }
  }
  const res = await fetch(new Request(lazyKey(f), { cache: 'reload' }));
  if (res.ok) await cache.put(lazyKey(f), res);
}

self.addEventListener('install', (event) => {
  /* each file is asked for under this version's own address, so a copy of the previous version that the
     web host still holds can never be mixed in */
  const versioned = (f) => new Request(f + (f.indexOf('?') < 0 ? '?' : '&') + 'v=' + VERSION, { cache: 'reload' });
  event.waitUntil(
    caches.open(CACHE)
      .then(async (cache) => {
        await cache.addAll(FILES.map(versioned));
        /* carry over the sound files of earlier builds that are unchanged (nothing new is downloaded here). The
           earlier stores are opened once, and the files copied a batch at a time: with over a thousand clips, one
           at a time would hold the new build back for many seconds */
        const olds = [];
        for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE) olds.push(await caches.open(k));
        const files = olds.length ? Object.keys(LAZY) : [];
        for (let i = 0; i < files.length; i += 50) {
          await Promise.all(files.slice(i, i + 50).map(async (f) => {
            for (const old of olds) {
              const res = await old.match(lazyKey(f));
              if (res) { await cache.put(lazyKey(f), res); return; }
            }
          }));
        }
      })
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  const lazy = lazyOf(request.url);
  if (lazy) {
    event.respondWith(
      caches.open(CACHE)
        .then(async (cache) => (await cache.match(lazyKey(lazy))) || (await keepLazy(cache, lazy), await cache.match(lazyKey(lazy))) || fetch(request))
        .catch(() => fetch(request))
    );
    return;
  }
  event.respondWith(
    caches.open(CACHE)
      .then(async (cache) => {
        const stored = await cache.match(request, { ignoreSearch: true });
        if (stored) return stored;
        /* opening the app by any address in its own folder gets the app's one page; an address in a folder
           below it belongs to something else kept there (another level's app, say) and goes to the network */
        if (request.mode === 'navigate') {
          const path = new URL(request.url).pathname;
          if (path.startsWith(HOME) && !path.slice(HOME.length).includes('/')) {
            const page = await cache.match('./index.html', { ignoreSearch: true });
            if (page) return page;
          }
        }
        return fetch(request);
      })
      /* the store could not be opened: fall back to the network */
      .catch(() => fetch(request))
  );
});

/* the app names the learner's level: store all of that level's sound for offline use, in the background */
self.addEventListener('message', (event) => {
  const lv = event.data && event.data.keepLevel;
  if (typeof lv !== 'string' || !/^n\d$/.test(lv)) return;
  const mine = Object.keys(LAZY).filter((f) => f.indexOf('sound-course-' + lv + '-') >= 0);
  event.waitUntil(caches.open(CACHE).then(async (cache) => { for (const f of mine) { try { await keepLazy(cache, f); } catch (e) { /* offline: try again next time */ } } }));
});
